<script setup lang="ts">
import { onUnmounted, ref, watch } from "vue";
import { request, query, type Page, type SmsReceivingAlias } from "@papilio/api";
import { faDate, faNumber } from "@papilio/ui";
import { useI18n } from "vue-i18n";
const props=defineProps<{realmId:number}>();
const {t}=useI18n();
const rows=ref<SmsReceivingAlias[]>([]),page=ref(1),pages=ref(1),loading=ref(false),error=ref("");let alive=true,sequence=0;
async function load():Promise<void>{const id=props.realmId,key=++sequence;loading.value=true;error.value="";try{const result=await request<Page<SmsReceivingAlias>>(`/v1/admin/payments/sms-origins/receiving-realms/${id}/aliases?${query({page:page.value})}`);if(!alive||key!==sequence||props.realmId!==id)return;rows.value=result.data;pages.value=result.meta.pager?.total_pages??1;}catch(cause){if(alive&&key===sequence)error.value=cause instanceof Error?cause.message:t("errors.request_failed");}finally{if(alive&&key===sequence)loading.value=false;}}
watch(()=>props.realmId,()=>{page.value=1;rows.value=[];void load();},{immediate:true});onUnmounted(()=>{alive=false;++sequence;});
</script>
<template><section :aria-label="t('paymentConfig.aliases.aria')"><div class="page-head"><h3>{{t('paymentConfig.aliases.title')}}</h3><button class="btn small secondary" :disabled="loading" @click="load">{{t('paymentConfig.aliases.refresh')}}</button></div><p v-if="error" class="message error" role="alert">{{error}}</p><div class="table-wrap"><table class="data-table"><thead><tr><th>{{t('paymentConfig.aliases.alias')}}</th><th>{{t('paymentConfig.aliases.method')}}</th><th>{{t('paymentConfig.aliases.digest')}}</th><th>{{t('paymentConfig.aliases.namespace')}}</th><th>{{t('paymentConfig.aliases.created')}}</th></tr></thead><tbody><tr v-for="row in rows" :key="row.id"><td>#{{faNumber(row.id)}}</td><td>{{row.kind==='card'?t('paymentConfig.destination.card'):row.kind==='iban'?t('paymentConfig.destination.iban'):t('paymentConfig.destination.accountType')}}</td><td><code>{{row.account_sha256}}</code></td><td>{{row.bank_namespace??t('paymentConfig.aliases.notRequired')}}</td><td>{{faDate(row.created_at)}}</td></tr></tbody></table></div><p v-if="loading">{{t('paymentConfig.aliases.loading')}}</p><p v-else-if="!rows.length&&!error">{{t('paymentConfig.aliases.empty')}}</p><div class="pager"><button :disabled="loading||page<=1" :aria-label="t('paymentConfig.previousPage')" @click="page--;load()">‹</button><span>{{faNumber(page)}} / {{faNumber(pages)}}</span><button :disabled="loading||page>=pages" :aria-label="t('paymentConfig.nextPage')" @click="page++;load()">›</button></div></section></template>
<style scoped>code{overflow-wrap:anywhere}</style>
